insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-001', '["phrase"]'::jsonb, '{"advanced-native-001-v1-audio":{"type":"mc","answers":["留在熟悉、安全的做法或環境；不一定表示懶惰。"],"options":["這句表示事情一定很容易。","這句的重點是準確的日期和時間。","留在熟悉、安全的做法或環境；不一定表示懶惰。","這句只在描述一個具體地點。"]},"advanced-native-001-v2-reply":{"type":"mc","answers":["She prefers work she already knows.","She feels safer with familiar tasks.","She tends to stay in her comfort zone.","She has not felt ready to try something new."],"options":["She prefers work she already knows.","She feels safer with familiar tasks.","She tends to stay in her comfort zone.","She has not felt ready to try something new."]},"advanced-native-001-v1-scene":{"type":"mc","answers":["They are staying in their comfort zone."],"options":["They are staying in their comfort zone.","They have forgotten how to cook.","They are cooking without any effort."]},"advanced-native-001-v1-contrast":{"type":"mc","answers":["他是否因為害怕風險而避開新機會。"],"options":["他的薪金是否比你高。","他是否準時下班。","他是否因為害怕風險而避開新機會。"]},"advanced-native-001-v1-branch":{"type":"mc","answers":["You could start with a small group if you want to step outside your comfort zone."],"options":["You could start with a small group if you want to step outside your comfort zone.","You are lazy because you stay in your comfort zone.","Your comfort zone is a real room you should leave."]},"advanced-native-001-v1-final":{"type":"open","answers":["She has stayed in her comfort zone, but this new project could help her grow.","She usually stays in her comfort zone. Maybe this is a good chance to try something new."],"options":[]}}'::jsonb),
('advanced-native-002', '["phrase"]'::jsonb, '{"advanced-native-002-v1-audio":{"type":"mc","answers":["繼續前進，卻只付出很少努力；可帶輕微批評意味。"],"options":["這句只在描述一個具體地點。","這句表示事情一定很容易。","這句的重點是準確的日期和時間。","繼續前進，卻只付出很少努力；可帶輕微批評意味。"]},"advanced-native-002-v2-reply":{"type":"mc","answers":["He has been doing only the minimum.","He is coasting along instead of challenging himself.","He has not been practising enough.","He keeps relying on what he already knows."],"options":["He has been doing only the minimum.","He is coasting along instead of challenging himself.","He has not been practising enough.","He keeps relying on what he already knows."]},"advanced-native-002-v1-scene":{"type":"mc","answers":["He is coasting along."],"options":["He is working around the clock.","He is coasting along.","He is making rapid progress."]},"advanced-native-002-v1-contrast":{"type":"mc","answers":["她每天刻意練習新技巧，水平穩定上升。"],"options":["她每天刻意練習新技巧，水平穩定上升。","他做最低限度的工作，暫時仍能過關。","球隊一直靠早前的優勢撐下去。"]},"advanced-native-002-v1-branch":{"type":"mc","answers":["We can''t just coast along; let''s plan for next month."],"options":["We must stop the project because the team has already failed.","We can''t just coast along; let''s plan for next month.","Let''s coast along so we can improve faster."]},"advanced-native-002-v1-final":{"type":"open","answers":["We''ve been coasting along with the same songs. Let''s practise a new set.","The band is coasting along, so we should learn some new material."],"options":[]}}'::jsonb),
('advanced-native-003', '["phrase"]'::jsonb, '{"advanced-native-003-v1-audio":{"type":"mc","answers":["一件讓人意識到問題、需要改變的事；不是真正的電話或鬧鐘。"],"options":["一件讓人意識到問題、需要改變的事；不是真正的電話或鬧鐘。","這句只在描述一個具體地點。","這句表示事情一定很容易。","這句的重點是準確的日期和時間。"]},"advanced-native-003-v2-reply":{"type":"mc","answers":["It showed us that our planning needs to change.","It was a wake-up call for the whole team.","It made us take the schedule more seriously.","It reminded us to check progress earlier."],"options":["It showed us that our planning needs to change.","It was a wake-up call for the whole team.","It made us take the schedule more seriously.","It reminded us to check progress earlier."]},"advanced-native-003-v1-scene":{"type":"mc","answers":["A wake-up call."],"options":["A wake-up call.","A friendly reminder about the weather.","A lucky break."]},"advanced-native-003-v1-contrast":{"type":"mc","answers":["手機每天早上準時響，提醒你起床。"],"options":["朋友的健康警告令他改變飲食。","手機每天早上準時響，提醒你起床。","一份差的報告令公司重新檢查品質。"]},"advanced-native-003-v1-branch":{"type":"mc","answers":["That sounds like a wake-up call; your new reminder system should help."],"options":["That sounds like a wake-up call; your new reminder system should help.","That was a wake-up call, so you must never apply again.","Your calendar is the wake-up call that rang at seven."]},"advanced-native-003-v1-final":{"type":"open","answers":["Running over time was a wake-up call. We will rehearse before the next presentation.","Our last presentation was a wake-up call, so we''ll time our rehearsal next time."],"options":[]}}'::jsonb),
('advanced-native-004', '["phrase"]'::jsonb, '{"advanced-native-004-v1-audio":{"type":"mc","answers":["未有充分準備，就被迫應付困難的工作或處境；借用泳池深水區的意象。"],"options":["這句的重點是準確的日期和時間。","未有充分準備，就被迫應付困難的工作或處境；借用泳池深水區的意象。","這句只在描述一個具體地點。","這句表示事情一定很容易。"]},"advanced-native-004-v2-reply":{"type":"mc","answers":["She had to lead a meeting with no preparation.","She was thrown in at the deep end.","She faced a difficult task straight away.","She had to learn while doing the job."],"options":["She had to lead a meeting with no preparation.","She was thrown in at the deep end.","She faced a difficult task straight away.","She had to learn while doing the job."]},"advanced-native-004-v1-scene":{"type":"mc","answers":["She was thrown in at the deep end."],"options":["She chose the easiest task.","She was thrown in at the deep end.","She took a relaxing swim."]},"advanced-native-004-v1-contrast":{"type":"mc","answers":["他受了完整訓練，先觀察三個月，才自願接簡單任務。"],"options":["她沒有帶隊經驗，突然要代替主管主持簡報。","他第一天工作就被安排獨立應付投訴。","他受了完整訓練，先觀察三個月，才自願接簡單任務。"]},"advanced-native-004-v1-branch":{"type":"mc","answers":["You were thrown in at the deep end. How did you manage?"],"options":["You were thrown in at the deep end. How did you manage?","You swam in the deep end, so the children must be wet.","You chose to avoid every difficult task."]},"advanced-native-004-v1-final":{"type":"open","answers":["She was thrown in at the deep end on her first shift, but she stayed calm.","Life threw her in at the deep end when she had to handle the rush alone."],"options":[]}}'::jsonb),
('advanced-native-005', '["phrase"]'::jsonb, '{"advanced-native-005-v1-audio":{"type":"mc","answers":["某段經歷塑造一個人的能力或性格；自然句型是 be the making of someone。"],"options":["這句表示事情一定很容易。","這句的重點是準確的日期和時間。","某段經歷塑造一個人的能力或性格；自然句型是 be the making of someone。","這句只在描述一個具體地點。"]},"advanced-native-005-v2-reply":{"type":"mc","answers":["She became much more independent.","It helped her grow in confidence.","She learned to manage life on her own.","It was the making of her."],"options":["She became much more independent.","It helped her grow in confidence.","She learned to manage life on her own.","It was the making of her."]},"advanced-native-005-v1-scene":{"type":"mc","answers":["Running the school paper was the making of her."],"options":["Running the school paper manufactured her.","The paper was made by her personality.","Running the school paper was the making of her."]},"advanced-native-005-v1-contrast":{"type":"mc","answers":["That difficult apprenticeship was the making of him."],"options":["That difficult apprenticeship was the making of him.","The apprenticeship was the making of a chair.","He was making of the apprenticeship."]},"advanced-native-005-v1-branch":{"type":"mc","answers":["It sounds like that year was the making of you."],"options":["It sounds like that year was the making of you.","It sounds like the year made a factory of you.","It sounds like you learned nothing at all."]},"advanced-native-005-v1-final":{"type":"open","answers":["Caring for the community garden was the making of her; she became more patient and responsible.","That year in the garden was the making of her. She learned to take responsibility."],"options":[]}}'::jsonb)
